import { z } from "zod";
import { apiError, dbError, jsonResponse, parseJson, rejectCrossOrigin, requireApiUser } from "@/lib/http";
import { OPEN_BATCH, openingSchema } from "@/lib/lootboxes";

const openSchema = z
  .object({
    /** Generated by the client per batch; repeating it returns the same stored results. */
    opening: z.uuid(),
    case: z.string().regex(/^[a-z][a-z0-9-]{0,31}$/),
    quantity: z.number().int().min(1).max(OPEN_BATCH, `Open up to ${OPEN_BATCH} cases at a time.`),
  })
  .strict();

/** Open one batch: the database consumes the cases and rolls and stores every result before replying. */
export async function POST(request: Request) {
  const rejected = rejectCrossOrigin(request);
  if (rejected) return rejected;
  const ctx = await requireApiUser();
  if (ctx instanceof Response) return ctx;
  const parsed = await parseJson(request, openSchema);
  if ("response" in parsed) return parsed.response;

  const { data, error } = await ctx.supabase.rpc("open_loot_cases", { p_opening: parsed.data.opening, p_case: parsed.data.case, p_quantity: parsed.data.quantity });
  if (error) return dbError(error, "The cases couldn't be opened. None were used.");
  const opening = openingSchema.safeParse(data);
  if (!opening.success) return apiError(500, "server_error", "The opening couldn't be read. Reload to see your saved results.");
  return jsonResponse(opening.data);
}
